      conversationId,
      more: self.getChatGPTModePayload(),
      streamContext: { ...streamContext, conversationId: streamContext.conversationId ?? conversationId ?? null },
      ondone: data => ondone?.(data),
      onstream: data => onstream?.(data)
    })
  };
}

